/**
 * The contract `progress.tsx` (native) and `progress.web.tsx` (web) both implement. Its own module
 * because Metro resolves `./progress` to `progress.web.tsx` on web.
 */

export type ProgressBaseProps = {
  /**
   * How much is done, from 0 to `max`. Clamped to that range. Left out (or `null`), the bar is
   * indeterminate: a third of the track sweeping across it, and announced with no value, as
   * Radix's is. Under reduced motion the sweep holds still in the middle, off the start, so it is
   * never read as an amount.
   */
  value?: number | null | undefined;
  /** What `value` is out of. 100 unless given, so a percentage needs nothing. */
  max?: number | undefined;
  /** What is progressing — "Re-embedding progress". The bar's accessible name. */
  label?: string | undefined;
  /**
   * The value in words, read instead of the bare number: "1,204 of 5,880 turns". Without it a
   * screen reader says the percentage, which is right when the number means nothing else.
   */
  valueLabel?: string | undefined;
  /** On the track, the full-width bar the fill is drawn in. A different height is an `h-*` here. */
  className?: string | undefined;
  /** The filled part: `bg-negative` for a context window nearly full. */
  indicatorClassName?: string | undefined;
};

/** What `max` is when nobody gives one, which makes `value` a percentage. */
export const DEFAULT_MAX = 100;
const PERCENT = 100;

/**
 * The value as the bar draws and announces it: `max` made usable, `value` clamped into it, and
 * the share of the track to fill. `now` is `undefined` for an indeterminate bar.
 */
export function progressState(
  value: number | null | undefined,
  max: number,
): { limit: number; now: number | undefined; percent: number } {
  // A zero or negative `max` has no fraction to draw; treat it as nothing done rather than NaN.
  const limit = max > 0 ? max : DEFAULT_MAX;
  const known = typeof value === "number" && Number.isFinite(value);
  const now = known ? Math.min(Math.max(value, 0), limit) : undefined;
  const percent = now === undefined ? 0 : (now / limit) * PERCENT;
  return { limit, now, percent };
}

/**
 * The track. Its `/50` edge is what shows the bar's whole length: 3:1 from the page and a card in
 * every palette, the edge a control has, where the `/10` fill alone was 1.24:1. The fill inside
 * stays `/10`, because a `/50` fill would leave the indicator 2:1 from it in Monokai.
 */
export const progressTrackClass =
  "h-2 w-full overflow-hidden rounded-full border border-foreground/50 bg-foreground/10";

/** The indicator, determinate or sweeping. */
export const progressIndicatorClass = "h-full bg-neutral";

/** The indeterminate segment's share of the track: a third, so it reads as a part moving. */
export const SWEEP_WIDTH = "33.333%";

/** One sweep, from off the start to off the end. */
export const SWEEP_DURATION_MS = 1500;

/**
 * Where the segment is, in its own widths, at the start and the end of a sweep: one width before
 * the track, and past its end. It is a third of the track, so three widths is the end.
 */
export const SWEEP_FROM = -1;
export const SWEEP_TO = 3;

/** Where it rests under reduced motion, in its own widths: the middle third. */
export const SWEEP_REST = 1;

/**
 * A horizontal bar showing how much of something is done. `value` means what shadcn's means, a
 * number from 0 to `max` (100 unless said otherwise), and it is clamped before it is drawn or
 * announced. `progress.web.tsx` is the web counterpart and `progress-base.ts` holds what they
 * share.
 *
 * With no `value` the bar is indeterminate: announced with no `aria-valuenow`, and drawn as a third
 * of the track sweeping across it, so it never looks like 0% (#487). The sweep is `Animated` on the
 * native driver, measured from the track's own width, and the compiler refuses `Animated`, which
 * is why the web half is hand-written. Under Reduce Motion the segment holds still in the middle
 * third: a sweep is a slide, which reduced motion stops, and a segment off the start is not an
 * amount. The determinate indicator's width is a style, since a class built from a number is one
 * Tailwind never generates. `label` names the bar, as an `aria-label` does.
 *
 * The segment is `View` wrapped by `createAnimatedComponent` rather than `Animated.View`, because
 * `View` is the one NativeWind hands a `className` to, and `indicatorClassName` has to reach it.
 */
import type * as React from "react";
import { useEffect, useRef, useState } from "react";
import { Animated, Easing, type LayoutChangeEvent, Platform, View } from "react-native";
import {
  DEFAULT_MAX,
  type ProgressBaseProps,
  progressIndicatorClass,
  progressState,
  progressTrackClass,
  SWEEP_DURATION_MS,
  SWEEP_FROM,
  SWEEP_REST,
  SWEEP_TO,
  SWEEP_WIDTH,
} from "@/components/ui/progress-base";
import { useReducedMotion } from "@/components/ui/reduced-motion";
import { cn } from "@/lib/utils";

export type ProgressProps = Omit<React.ComponentProps<typeof View>, "className" | "children"> &
  ProgressBaseProps;

/** The segment is a third of the track, so one of its widths is the track's over this. */
const SEGMENTS_PER_TRACK = 3;

const SweepingView = Animated.createAnimatedComponent(View);

/** A third of the track, sweeping from before its start to past its end. */
function Sweep({ className }: { className?: string | undefined }) {
  const reducedMotion = useReducedMotion();
  const [segment, setSegment] = useState(0);
  const sweep = useRef(new Animated.Value(SWEEP_REST)).current;

  useEffect(() => {
    // Nothing to sweep until the track has a width, and nothing moves under Reduce Motion.
    if (reducedMotion || segment === 0) {
      sweep.setValue(SWEEP_REST);
      return;
    }
    sweep.setValue(SWEEP_FROM);
    const loop = Animated.loop(
      Animated.timing(sweep, {
        toValue: SWEEP_TO,
        duration: SWEEP_DURATION_MS,
        easing: Easing.inOut(Easing.ease),
        useNativeDriver: true,
      }),
    );
    loop.start();
    return () => loop.stop();
  }, [sweep, reducedMotion, segment]);

  const measure = (event: LayoutChangeEvent) =>
    setSegment(event.nativeEvent.layout.width / SEGMENTS_PER_TRACK);
  const translateX = sweep.interpolate({
    inputRange: [SWEEP_FROM, SWEEP_TO],
    outputRange: [SWEEP_FROM * segment, SWEEP_TO * segment],
  });

  return (
    <View className="h-full w-full" onLayout={measure}>
      <SweepingView
        testID="progress-indicator"
        className={cn(progressIndicatorClass, className)}
        style={{ width: SWEEP_WIDTH, transform: [{ translateX }] }}
      />
    </View>
  );
}

/** A horizontal bar showing how much of something is done. */
export function Progress({
  value,
  max = DEFAULT_MAX,
  label,
  valueLabel,
  className,
  indicatorClassName,
  ...props
}: ProgressProps) {
  const { limit, now, percent } = progressState(value, max);

  return (
    <View
      testID="progress"
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={limit}
      {...(now === undefined ? {} : { "aria-valuenow": now })}
      {...(valueLabel ? { "aria-valuetext": valueLabel } : {})}
      {...props}
      {...(label ? { "aria-label": label } : {})}
      className={cn(progressTrackClass, className)}
    >
      {now === undefined ? (
        <Sweep className={indicatorClassName} />
      ) : (
        <View
          testID="progress-indicator"
          className={cn(
            progressIndicatorClass,
            Platform.select({
              web: "transition-[width] motion-reduce:transition-none",
              default: undefined,
            }),
            indicatorClassName,
          )}
          style={{ width: `${percent}%` }}
        />
      )}
    </View>
  );
}

/**
 * The web progress bar: a `<div role="progressbar">` with every `<div>` prop passed through.
 * `progress.tsx` is the native counterpart and says why this half is hand-written;
 * `progress-base.ts` holds what they share.
 *
 * The indeterminate sweep is the Web Animations API rather than a keyframe class, because a
 * keyframe would have to live in an app's stylesheet and this item would not work without it. It
 * reads `useReducedMotion()`, as the native half does, and under reduced motion the segment holds
 * still in the middle third.
 */
import type * as React from "react";
import { useEffect, useRef } from "react";
import {
  DEFAULT_MAX,
  type ProgressBaseProps,
  progressIndicatorClass,
  progressState,
  progressTrackClass,
  SWEEP_DURATION_MS,
  SWEEP_FROM,
  SWEEP_REST,
  SWEEP_TO,
  SWEEP_WIDTH,
} from "@/components/ui/progress-base";
import { useReducedMotion } from "@/components/ui/reduced-motion";
import { cn } from "@/lib/utils";

export type ProgressProps = Omit<React.ComponentPropsWithoutRef<"div">, "className" | "children"> &
  ProgressBaseProps;

const PERCENT = 100;

/** A translate of the segment by this many of its own widths. */
const shift = (widths: number) => `translateX(${widths * PERCENT}%)`;

/** A third of the track, sweeping from before its start to past its end. */
function Sweep({ className }: { className?: string | undefined }) {
  const reducedMotion = useReducedMotion();
  const segment = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = segment.current;
    // `animate` is missing from a test DOM without the Web Animations API; the segment rests.
    if (reducedMotion || !element || typeof element.animate !== "function") {
      return;
    }
    const sweep = element.animate(
      [{ transform: shift(SWEEP_FROM) }, { transform: shift(SWEEP_TO) }],
      {
        duration: SWEEP_DURATION_MS,
        easing: "ease-in-out",
        iterations: Number.POSITIVE_INFINITY,
      },
    );
    return () => sweep.cancel();
  }, [reducedMotion]);

  return (
    <div
      ref={segment}
      data-slot="progress-indicator"
      className={cn(progressIndicatorClass, className)}
      style={{ width: SWEEP_WIDTH, transform: shift(SWEEP_REST) }}
    />
  );
}

/** A horizontal bar showing how much of something is done. */
export function Progress({
  value,
  max = DEFAULT_MAX,
  label,
  valueLabel,
  className,
  indicatorClassName,
  ...props
}: ProgressProps) {
  const { limit, now, percent } = progressState(value, max);
  // Radix's three states, so a shadcn call site's `data-[state=complete]:` still matches.
  const state = now === undefined ? "indeterminate" : now === limit ? "complete" : "loading";

  return (
    <div
      data-slot="progress"
      data-state={state}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={limit}
      {...(now === undefined ? {} : { "aria-valuenow": now })}
      {...(valueLabel ? { "aria-valuetext": valueLabel } : {})}
      {...props}
      {...(label ? { "aria-label": label } : {})}
      className={cn(progressTrackClass, className)}
    >
      {now === undefined ? (
        <Sweep className={indicatorClassName} />
      ) : (
        <div
          data-slot="progress-indicator"
          className={cn(
            progressIndicatorClass,
            "transition-[width] motion-reduce:transition-none",
            indicatorClassName,
          )}
          style={{ width: `${percent}%` }}
        />
      )}
    </div>
  );
}
